import { useState, useEffect } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { 
  LineChart, 
  Line, 
  XAxis, 
  YAxis, 
  CartesianGrid, 
  Tooltip, 
  ResponsiveContainer,
  AreaChart,
  Area,
  RadarChart,
  PolarGrid,
  PolarAngleAxis,
  PolarRadiusAxis,
  Radar
} from 'recharts';
import { TrendingUp, Calendar, Target, Users, AlertCircle, CheckCircle } from 'lucide-react';
import { getInitiatives, getDepartments } from '../lib/database';
import { useToast } from '../hooks/use-toast';

function PerformanceTab({ statistics, onDataUpdate }) {
  const { toast } = useToast();
  const [initiatives, setInitiatives] = useState([]);
  const [departments, setDepartments] = useState([]);
  const [timeFilter, setTimeFilter] = useState('6months');
  const [departmentFilter, setDepartmentFilter] = useState('الكل');

  useEffect(() => {
    loadData();
  }, []);

  const loadData = async () => {
    try {
      const [initiativesData, departmentsData] = await Promise.all([
        getInitiatives(),
        getDepartments()
      ]);
      setInitiatives(initiativesData);
      setDepartments(departmentsData);
    } catch (error) {
      console.error('Error loading data:', error);
      toast({
        title: "خطأ",
        description: "حدث خطأ في تحميل البيانات",
        variant: "destructive",
      });
    }
  };

  // Generate performance trend data
  const generateTrendData = () => {
    const months = ['يناير', 'فبراير', 'مارس', 'أبريل', 'مايو', 'يونيو', 'يوليو', 'أغسطس', 'سبتمبر'];
    return months.map((month, index) => ({
      month,
      completion: Math.min(100, 20 + (index * 8) + Math.random() * 10),
      quality: Math.min(100, 70 + (index * 3) + Math.random() * 5),
      efficiency: Math.min(100, 60 + (index * 4) + Math.random() * 8),
      satisfaction: Math.min(100, 75 + (index * 2) + Math.random() * 6)
    }));
  };

  // Department performance radar data
  const generateDepartmentRadar = () => {
    return departments.slice(0, 5).map(dept => ({
      department: dept.name,
      completion: Math.floor(Math.random() * 40) + 60,
      quality: Math.floor(Math.random() * 30) + 70,
      efficiency: Math.floor(Math.random() * 35) + 65,
      innovation: Math.floor(Math.random() * 25) + 75,
      overall: Math.floor(Math.random() * 20) + 80
    }));
  };

  const trendData = generateTrendData();
  const departmentData = generateDepartmentRadar();

  // KPI calculations
  const completedInitiatives = initiatives.filter(i => i.status === 'مكتملة').length;
  const inProgressInitiatives = initiatives.filter(i => i.status === 'قيد التنفيذ').length;
  const averageCompletion = initiatives.length > 0 ? 
    Math.round(initiatives.reduce((sum, i) => sum + i.completion_percentage, 0) / initiatives.length) : 0;
  
  const budgetUtilization = initiatives.length > 0 ? 
    Math.round((initiatives.reduce((sum, i) => sum + i.used_budget, 0) / initiatives.reduce((sum, i) => sum + i.planned_budget, 0)) * 100) : 0;

  const onTimeDelivery = initiatives.length > 0 ? 
    Math.round((initiatives.filter(i => i.status === 'مكتملة' || i.status === 'قيد التنفيذ').length / initiatives.length) * 100) : 0;

  return (
    <div className="space-y-6">
      {/* KPI Overview */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
        <Card>
          <CardContent className="p-4">
            <div className="flex items-center justify-between mb-2">
              <span className="text-sm font-medium text-gray-600">إجمالي المبادرات</span>
              <Target className="h-5 w-5" style={{color: 'var(--brand-orange)'}} />
            </div>
            <div className="text-2xl font-bold" style={{color: 'var(--brand-orange)'}}>{initiatives.length}</div>
            <div className="text-xs text-gray-500">
              {completedInitiatives} مكتملة • {inProgressInitiatives} قيد التنفيذ
            </div>
          </CardContent>
        </Card>

        <Card>
          <CardContent className="p-4">
            <div className="flex items-center justify-between mb-2">
              <span className="text-sm font-medium text-gray-600">متوسط نسبة الإكمال</span>
              <TrendingUp className="h-5 w-5 text-blue-600" />
            </div>
            <div className="text-2xl font-bold text-blue-600">{averageCompletion}%</div>
            <div className="text-xs text-gray-500">الهدف: 85%</div>
          </CardContent>
        </Card>

        <Card>
          <CardContent className="p-4">
            <div className="flex items-center justify-between mb-2">
              <span className="text-sm font-medium text-gray-600">استخدام الميزانية</span>
              <AlertCircle className="h-5 w-5 text-yellow-600" />
            </div>
            <div className="text-2xl font-bold text-yellow-600">{budgetUtilization}%</div>
            <div className="text-xs text-gray-500">
              {initiatives.reduce((sum, i) => sum + i.used_budget, 0).toLocaleString()} د.إ من {initiatives.reduce((sum, i) => sum + i.planned_budget, 0).toLocaleString()} د.إ
            </div>
          </CardContent>
        </Card>

        <Card>
          <CardContent className="p-4">
            <div className="flex items-center justify-between mb-2">
              <span className="text-sm font-medium text-gray-600">نقاط الجائزة</span>
              <CheckCircle className="h-5 w-5 text-green-600" />
            </div>
            <div className="text-2xl font-bold text-green-600">{statistics?.totalAwardPoints || 0}</div>
            <div className="text-xs text-gray-500">
              {statistics?.strengthPoints || 0} قوة • {statistics?.improvementPoints || 0} تحسين
            </div>
          </CardContent>
        </Card>
      </div>

      {/* Performance KPIs */}
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2" style={{color: 'var(--brand-orange)'}}>
            <Target className="h-5 w-5" />
            مؤشرات الأداء الرئيسية
          </CardTitle>
        </CardHeader>
        <CardContent>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
            <div className="text-center">
              <div className="text-sm font-medium text-gray-600 mb-2">معدل الإنجاز</div>
              <div className="text-3xl font-bold text-orange-600 mb-1">40%</div>
              <div className="text-xs text-gray-500">الهدف: 85%</div>
              <div className="w-full bg-gray-200 rounded-full h-2 mt-2">
                <div className="bg-orange-600 h-2 rounded-full" style={{width: '40%'}}></div>
              </div>
            </div>
            
            <div className="text-center">
              <div className="text-sm font-medium text-gray-600 mb-2">الالتزام بالمواعيد</div>
              <div className="text-3xl font-bold text-green-600 mb-1">80%</div>
              <div className="text-xs text-gray-500">الهدف: 90%</div>
              <div className="w-full bg-gray-200 rounded-full h-2 mt-2">
                <div className="bg-green-600 h-2 rounded-full" style={{width: '80%'}}></div>
              </div>
            </div>
            
            <div className="text-center">
              <div className="text-sm font-medium text-gray-600 mb-2">جودة التنفيذ</div>
              <div className="text-3xl font-bold text-blue-600 mb-1">92%</div>
              <div className="text-xs text-gray-500">الهدف: 95%</div>
              <div className="w-full bg-gray-200 rounded-full h-2 mt-2">
                <div className="bg-blue-600 h-2 rounded-full" style={{width: '92%'}}></div>
              </div>
            </div>
            
            <div className="text-center">
              <div className="text-sm font-medium text-gray-600 mb-2">رضا المستفيدين</div>
              <div className="text-3xl font-bold text-purple-600 mb-1">88%</div>
              <div className="text-xs text-gray-500">الهدف: 90%</div>
              <div className="w-full bg-gray-200 rounded-full h-2 mt-2">
                <div className="bg-purple-600 h-2 rounded-full" style={{width: '88%'}}></div>
              </div>
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Time Filters */}
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2" style={{color: 'var(--brand-orange)'}}>
            <Calendar className="h-5 w-5" />
            الفترة الزمنية
          </CardTitle>
        </CardHeader>
        <CardContent>
          <div className="flex gap-2 mb-4">
            {[
              { key: '3months', label: '3 أشهر' },
              { key: '6months', label: '6 أشهر' },
              { key: '1year', label: 'سنة' }
            ].map((filter) => (
              <Button
                key={filter.key}
                variant={timeFilter === filter.key ? "default" : "outline"}
                size="sm"
                onClick={() => setTimeFilter(filter.key)}
                style={timeFilter === filter.key ? {backgroundColor: 'var(--brand-orange)'} : {}}
              >
                {filter.label}
              </Button>
            ))}
          </div>
        </CardContent>
      </Card>

      {/* Performance Trends */}
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2" style={{color: 'var(--brand-orange)'}}>
            <TrendingUp className="h-5 w-5" />
            اتجاهات الأداء
          </CardTitle>
        </CardHeader>
        <CardContent>
          <div className="h-80">
            <ResponsiveContainer width="100%" height="100%">
              <AreaChart data={trendData}>
                <CartesianGrid strokeDasharray="3 3" />
                <XAxis dataKey="month" />
                <YAxis />
                <Tooltip />
                <Area 
                  type="monotone" 
                  dataKey="completion" 
                  stackId="1" 
                  stroke="var(--brand-orange)" 
                  fill="var(--brand-orange)" 
                  fillOpacity={0.6}
                  name="الإنجاز"
                />
                <Area 
                  type="monotone" 
                  dataKey="quality" 
                  stackId="2" 
                  stroke="#16a34a" 
                  fill="#16a34a" 
                  fillOpacity={0.6}
                  name="الجودة"
                />
                <Area 
                  type="monotone" 
                  dataKey="efficiency" 
                  stackId="3" 
                  stroke="#0ea5e9" 
                  fill="#0ea5e9" 
                  fillOpacity={0.6}
                  name="الكفاءة"
                />
              </AreaChart>
            </ResponsiveContainer>
          </div>
        </CardContent>
      </Card>

      {/* Department Performance Matrix */}
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2" style={{color: 'var(--brand-orange)'}}>
            <Users className="h-5 w-5" />
            مصفوفة أداء الإدارات
          </CardTitle>
        </CardHeader>
        <CardContent>
          <div className="overflow-x-auto">
            <table className="w-full border-collapse">
              <thead>
                <tr className="border-b border-gray-200">
                  <th className="text-right p-3 font-medium text-gray-700">الإدارة</th>
                  <th className="text-center p-3 font-medium text-gray-700">نسبة الإكمال</th>
                  <th className="text-center p-3 font-medium text-gray-700">الجودة</th>
                  <th className="text-center p-3 font-medium text-gray-700">الكفاءة</th>
                  <th className="text-center p-3 font-medium text-gray-700">الابتكار</th>
                  <th className="text-center p-3 font-medium text-gray-700">التقييم العام</th>
                </tr>
              </thead>
              <tbody>
                {departmentData.map((dept, index) => (
                  <tr key={index} className="border-b border-gray-100 hover:bg-gray-50">
                    <td className="p-3 text-sm font-medium">{dept.department}</td>
                    <td className="p-3 text-center">
                      <div className="flex items-center justify-center">
                        <div className="w-16 bg-gray-200 rounded-full h-2 mr-2">
                          <div 
                            className="bg-blue-600 h-2 rounded-full" 
                            style={{width: `${dept.completion}%`}}
                          ></div>
                        </div>
                        <span className="text-sm">{dept.completion}%</span>
                      </div>
                    </td>
                    <td className="p-3 text-center">
                      <div className="flex items-center justify-center">
                        <div className="w-16 bg-gray-200 rounded-full h-2 mr-2">
                          <div 
                            className="bg-green-600 h-2 rounded-full" 
                            style={{width: `${dept.quality}%`}}
                          ></div>
                        </div>
                        <span className="text-sm">{dept.quality}%</span>
                      </div>
                    </td>
                    <td className="p-3 text-center">
                      <div className="flex items-center justify-center">
                        <div className="w-16 bg-gray-200 rounded-full h-2 mr-2">
                          <div 
                            className="bg-yellow-600 h-2 rounded-full" 
                            style={{width: `${dept.efficiency}%`}}
                          ></div>
                        </div>
                        <span className="text-sm">{dept.efficiency}%</span>
                      </div>
                    </td>
                    <td className="p-3 text-center">
                      <div className="flex items-center justify-center">
                        <div className="w-16 bg-gray-200 rounded-full h-2 mr-2">
                          <div 
                            className="bg-purple-600 h-2 rounded-full" 
                            style={{width: `${dept.innovation}%`}}
                          ></div>
                        </div>
                        <span className="text-sm">{dept.innovation}%</span>
                      </div>
                    </td>
                    <td className="p-3 text-center">
                      <Badge 
                        className={`text-xs ${
                          dept.overall >= 90 ? 'bg-green-100 text-green-800' :
                          dept.overall >= 80 ? 'bg-blue-100 text-blue-800' :
                          dept.overall >= 70 ? 'bg-yellow-100 text-yellow-800' :
                          'bg-red-100 text-red-800'
                        }`}
                      >
                        {dept.overall >= 90 ? 'ممتاز' :
                         dept.overall >= 80 ? 'جيد جداً' :
                         dept.overall >= 70 ? 'جيد' : 'يحتاج تحسين'}
                      </Badge>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </CardContent>
      </Card>

      {/* Quick Actions */}
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2" style={{color: 'var(--brand-orange)'}}>
            <Target className="h-5 w-5" />
            إجراءات سريعة
          </CardTitle>
        </CardHeader>
        <CardContent>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            <Button 
              className="h-auto p-4 flex flex-col items-start gap-2"
              variant="outline"
              style={{borderColor: 'var(--brand-orange)'}}
            >
              <Calendar className="h-5 w-5" style={{color: 'var(--brand-orange)'}} />
              <div className="text-left">
                <div className="font-semibold">جدولة اجتماع مراجعة</div>
                <div className="text-xs text-gray-500">تحديد موعد لمراجعة التقدم</div>
              </div>
            </Button>
            
            <Button 
              className="h-auto p-4 flex flex-col items-start gap-2"
              variant="outline"
              style={{borderColor: 'var(--brand-orange)'}}
            >
              <TrendingUp className="h-5 w-5" style={{color: 'var(--brand-orange)'}} />
              <div className="text-left">
                <div className="font-semibold">إنشاء تقرير شهري</div>
                <div className="text-xs text-gray-500">تقرير شامل عن الإنجازات</div>
              </div>
            </Button>
            
            <Button 
              className="h-auto p-4 flex flex-col items-start gap-2"
              variant="outline"
              style={{borderColor: 'var(--brand-orange)'}}
            >
              <AlertCircle className="h-5 w-5" style={{color: 'var(--brand-orange)'}} />
              <div className="text-left">
                <div className="font-semibold">متابعة المتأخرات</div>
                <div className="text-xs text-gray-500">مراجعة المبادرات المتأخرة</div>
              </div>
            </Button>
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

export default PerformanceTab;
